import { useContext, useEffect, useId } from "react";
import { FeedbackContext } from "../feedbackContainer/feedbackContext";
import { useWarning } from "../feedbackProvider/hooks/useWarning";
export const Toast = ({ isOpen, header, type, onClose, hasIcon, action, id }) => {
    const { addToast, removeToast, toasts, toastsAnimation, toastsQueue, removedToastId, apiToastActions, setApiToastActions, mode } = useContext(FeedbackContext);
    const generatedId = useId();
    const localId = id || generatedId;
    const isInQueue = toastsQueue.some((toast) => toast.id === localId);
    const isRendered = toasts.some((toast) => toast.id === localId);
    const isAnimating = toastsAnimation.some((toast) => toast.id === localId);
    const isApi = mode === "api";
    const toastIndex = toasts.findIndex((alert) => alert.id === localId);
    const isInApiToasts = !!apiToastActions.find((toast) => toast.id === localId);
    useWarning({ mode, name: "toasts" });
    useEffect(() => {
        if (isApi) {
            if (isOpen && !isInApiToasts) {
                addToast({ header, id: localId, type, onClose: () => {
                        onClose();
                    }, hasIcon, action });
                return;
            }
            if (!isOpen && isInApiToasts) {
                removeToast(localId);
                onClose();
                return;
            }
            return;
        }
        if (isOpen && isInQueue && isRendered) {
            return;
        }
        if (isOpen && (!isInQueue && !isRendered)) {
            addToast({ header, id: localId, type, onClose: () => {
                    onClose();
                }, hasIcon, action });
        }
        if (!isOpen && isRendered && !isInQueue && !isAnimating) {
            if (toastIndex !== -1) {
                removedToastId.current = toastIndex;
            }
            removeToast(localId);
            onClose();
        }
    }, [
        localId,
        isOpen,
        header,
        type,
        addToast,
        onClose,
        removeToast,
        isInQueue,
        isRendered,
        isAnimating,
        toastIndex,
        removedToastId,
        hasIcon,
        action,
        isApi,
        apiToastActions,
        setApiToastActions,
        isInApiToasts
    ]);
    return null;
};
